SELECT singer.Name, singer.Age AS youngest_vocalists FROM singer JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID JOIN stadium ON singer_in_concert.Stadium_ID = stadium.Stadium_ID WHERE singer.Age = (SELECT MIN(Age) FROM singer)
SELECT DISTINCT singer.Name, singer.release_year FROM singer JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID JOIN stadium ON concert.Stadium_ID = stadium.Stadium_ID ORDER BY singer.Age ASC LIMIT 1;
