SELECT State, COUNT(singer_in_concert.Singer_ID) AS number_of_vocalists_per_country FROM singer_in_concert JOIN singer ON singer_in_concert.Singer_ID = singer.Singer_ID JOIN stadium ON singer_in_concert.concert_ID = concert.concert_ID GROUP BY State
SELECT DISTINCT singer.State, COUNT(singer.State) AS Count FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID GROUP BY singer.State;
SELECT singer.Singer_ID, singer.Name, singer.Country, singer_in_concert.Song_Name, singer_in_concert.Year, singer.Age, singer.Is_male, concert.Theme FROM singer INNER JOIN singer_in_concert ON singer.Singer_ID = singer_in_concert.Singer_ID INNER JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID WHERE singer.Age > (SELECT AVG(Song_Release_Year) FROM singer)
