SELECT stadium.Stadium_ID, singer.Name, concert.Year FROM concert JOIN singer ON singer_in_concert.Singer_ID = singer.Singer_ID JOIN stadium ON concert.Stadium_ID = stadium.Stadium_ID WHERE concert.Year BETWEEN 2020 AND 2025;
SELECT s.Name, c.Stadium_ID, c.Year FROM concert c JOIN singer_in_concert s ON c.concert_ID = s.concert_ID WHERE c.Year BETWEEN 2020 AND 2025;
SELECT AVG(Capacity), MAX(Capacity) FROM stadium;
SELECT AVG(Capacity) AS Average, MAX(Capacity) AS Maximum FROM stadium;
SELECT Name, AVG(Average) AS Average_Average FROM stadium INNER JOIN singer_in_concert ON stadium.Stadium_ID = singer_in_concert.concert_ID GROUP BY Name ORDER BY AVG(Average) DESC LIMIT 1;
SELECT Name, AVG(Average) AS Average_Average FROM stadium INNER JOIN singer_in_concert ON stadium.Stadium_ID = singer_in_concert.concert_ID INNER JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID GROUP BY Name ORDER BY AVG(Average) DESC LIMIT 1;
