SELECT stadium.Name, COUNT(singer_in_concert.Singer_ID) AS show_count FROM stadium JOIN singer_in_concert ON stadium.Stadium_ID = singer_in_concert.stadium_ID GROUP BY stadium.Name
SELECT COUNT(*) AS total_shows_per_stadium FROM singer_in_concert JOIN concert ON singer_in_concert.concert_ID = concert.concert_ID JOIN stadium ON singer_in_concert.Stadium_ID = stadium.Stadium_ID;
SELECT concert.Name, COUNT(singer_in_concert.Singer_ID) AS total_seats FROM concert JOIN singer_in_concert ON concert.concert_ID = singer_in_concert.concert_ID JOIN stadium ON singer_in_concert.Stadium_ID = stadium.Stadium_ID WHERE concert.Year = 2014 OR concert.Year > 2014 GROUP BY concert.Name, concert.Stadium_ID ORDER BY total_seats DESC;
SELECT s.Name, c.Capacity AS seats FROM concert c JOIN singer_in_concert s ON c.concert_ID = singer_in_concert.concert_ID JOIN stadium ON c.Stadium_ID = stadium.Stadium_ID WHERE c.Year > '2013' GROUP BY s.Name ORDER BY seats DESC LIMIT 1;
SELECT concert.Year, COUNT(singer_in_concert.Singer_ID) AS total_shows FROM concert JOIN singer_in_concert ON concert.concert_ID = singer_in_concert.concert_ID GROUP BY concert.Year ORDER BY total_shows DESC;
SELECT concert.Year, COUNT(singer_in_concert.Singer_ID) AS total_shows FROM concert JOIN singer_in_concert ON concert.concert_ID = singer_in_concert.concert_ID GROUP BY concert.Year ORDER BY total_shows DESC;
