SELECT visitor.Name, visitor.Level_of_membership FROM visitor JOIN museum ON visit.Museum_ID = museum.Museum_ID ORDER BY visitor.Age DESC;
SELECT museum.Museum_ID, museum.Name, COUNT(visitor.ID) AS total_visitors FROM museum INNER JOIN visit ON museum.Museum_ID = visit.Museum_ID INNER JOIN visitor ON visit.visitor_ID = visitor.ID GROUP BY museum.Museum_ID ORDER BY total_visitors DESC LIMIT 1;
