SELECT p.first_name, p.hand, p.rankings.ranking_points AS total_ranking_points FROM players p JOIN rankings r ON p.player_id = r.player_id GROUP BY p.first_name, p.hand
SELECT players.first_name, players.last_name, SUM(rankings.ranking_points) AS total_ranking_points FROM players INNER JOIN rankings ON players.player_id = rankings.player_id GROUP BY players.first_name, players.last_name
SELECT COUNT(DISTINCT players.country_code) AS count_of_participants FROM players;
SELECT COUNT(DISTINCT players.country_code) AS total_participants, players.country_code AS country FROM players GROUP BY players.country_code;
SELECT players.country_code FROM players JOIN rankings ON players.player_id = rankings.player_id WHERE rankings.ranking_points ORDER BY rankings.ranking_points DESC LIMIT 1;
SELECT country_code FROM players JOIN rankings ON players.player_id = rankings.player_id GROUP BY players.player_id ORDER BY ranking_points DESC LIMIT 1
SELECT player_id FROM players WHERE country_code IN (SELECT country_code FROM matches WHERE (loser_hand = 'hand' AND (SELECT COUNT(*) FROM players WHERE hand = 'hand' AND country_code = player_id) > 50)) GROUP BY player_id
SELECT country_code FROM players JOIN matches ON players.player_id = matches.loser_id WHERE matches.round = 1 AND matches.minutes > 50;
SELECT COUNT(*) AS total_trips FROM rankings INNER JOIN players ON rankings.player_id = players.player_id;
SELECT COUNT(DISTINCT rankings.ranking) AS total_travels_per_ranking_time FROM rankings JOIN players ON rankings.player_id = players.player_id;
SELECT year, COUNT(*) AS number_of_games_per_year FROM matches GROUP BY year;
SELECT year, COUNT(*) AS total_games FROM matches GROUP BY year
SELECT p.first_name, p.rankings.ranking FROM players p JOIN rankings ON p.player_id = rankings.player_id ORDER BY p.rankings.ranking ASC LIMIT 3;
SELECT p.first_name, p.last_name, r.ranking FROM players p JOIN rankings r ON p.player_id = r.player_id ORDER BY r.ranking ASC LIMIT 3;
SELECT COUNT(DISTINCT players.player_id) FROM players JOIN matches ON players.player_id = matches.winner_id JOIN rankings ON players.player_id = rankings.player_id WHERE rankings.ranking = 1;
SELECT COUNT(DISTINCT players.player_id) FROM players INNER JOIN matches ON players.player_id = matches.winner_id;
SELECT p.first_name, p.last_name, r.ranking_points FROM players p INNER JOIN rankings r ON p.player_id = r.player_id WHERE r.ranking_points ORDER BY r.ranking_points DESC LIMIT 1;
SELECT p.first_name, p.country_code, m.winner_rank_points AS winner_rank_points FROM players p JOIN matches m ON p.player_id = m.winner_id ORDER BY winner_rank_points DESC LIMIT 1;
SELECT COUNT(DISTINCT players.hand) AS number_of_participants FROM players;
SELECT COUNT(DISTINCT hand) AS total_participants, hand FROM players JOIN rankings ON players.player_id = rankings.player_id GROUP BY hand
SELECT COUNT(DISTINCT ship.id) FROM ship WHERE ship.disposition_of_ship = 'Captured'
SELECT name, tonnage FROM ship ORDER BY name ASC LIMIT 100;
SELECT battle.name, battle.date, battle.result FROM battle JOIN ship ON battle.id = ship.lost_in_battle;
SELECT MAX(killed), MIN(killed) FROM death;
SELECT AVG(death.injured) AS average_injuries_per_time FROM battle JOIN ship ON battle.id = ship.lost_in_battle;
SELECT death.note, death.killed, death.injured FROM death JOIN ship ON death.caused_by_ship_id = ship.id JOIN battle ON ship.lost_in_battle = battle.id WHERE ship.tonnage = 't'
SELECT battle.name, battle.result FROM battle JOIN ship ON battle.id = ship.lost_in_battle WHERE battle.bulgarian_commander != 'Boril'
SELECT b.id, b.name, s.name, d.note FROM battle b JOIN ship s ON b.id = s.lost_in_battle JOIN death d ON s.id = d.caused_by_ship_id WHERE d.note LIKE '%Brig%';
SELECT battle.id, battle.name, death.killed, death.injured FROM battle JOIN ship ON battle.id = ship.lost_in_battle JOIN death ON ship.id = death.caused_by_ship WHERE death.killed > 10 OR death.injured > 10;
SELECT ship.id, ship.name, battle.id, battle.date, battle.bulgarian_commander, battle.latin_commander, ship.lost_in_battle, ship.tonnage, ship.ship_type, ship.location, ship.disposition_of_ship, death.caused_by_ship_id, death.id, death.note, death.killed, death.injured, death.result FROM ship LEFT JOIN battle ON ship.lost_in_battle = battle.id LEFT JOIN death ON ship.id = death.caused_by_ship_id WHERE ship.lost_in_battle = (SELECT MAX(ship.lost_in_battle) FROM ship) GROUP BY ship.id, ship.name, ship.tonnage, ship.ship_type, ship.location, ship.disposition_of_ship, ship.id, ship.name, ship.tonnage, ship.ship_type, ship.location, ship.disposition_of_ship ORDER BY ship.id ASC;
SELECT DISTINCT name FROM battle JOIN ship ON battle.id = ship.lost_in_battle JOIN death ON battle.id = death.caused_by_ship WHERE bulgarian_commander = 'Kaloyan' AND latin_commander = 'Baldwin I';
SELECT COUNT(DISTINCT battle.id) FROM battle;
SELECT COUNT(*) FROM battle b JOIN ship s ON b.lost_in_battle = s.id WHERE s.tonnage = '225' AND b.result = 'loss'
SELECT battle.name, battle.date, ship.name, ship.tonnage, ship.ship_type, ship.location, ship.disposition_of_ship FROM battle JOIN ship ON battle.id = ship.lost_in_battle WHERE ship.name IN ('Lettice', 'HMS Atalanta')
SELECT battle.name, battle.result, battle.bulgarian_commander FROM battle JOIN ship ON battle.id = ship.lost_in_battle WHERE ship.location = 'English Channel' AND battle.result IS NULL;
SELECT death.note FROM death JOIN ship ON death.caused_by_ship_id = ship.id JOIN battle ON ship.lost_in_battle = battle.id WHERE battle.name LIKE '%East%';
SELECT Addresses.address_id, Addresses.line_1, Addresses.line_2 FROM Addresses WHERE Addresses.line_1 || ' ' || Addresses.line_2 = 'line 1 and line 2'
SELECT first_name, middle_name, last_name, other_address_details FROM Students ORDER BY first_name, middle_name, last_name LIMIT 2;
SELECT COUNT(*) FROM Courses;
SELECT COUNT(DISTINCT course_name) FROM Courses;
SELECT course_description, degree_summary_description FROM Degree_Programs INNER JOIN Degree_Programs ON Degree_Programs.degree_program_id = Degree_Programs.degree_program_id;
SELECT course_description, course_id FROM Courses ORDER BY course_description;
SELECT Addresses.zip_postcode FROM Addresses WHERE city = 'Port Chelsea' AND Addresses.address_id IS NOT NULL;
SELECT zip_postcode FROM Addresses WHERE city = 'Port Chelsea' AND state_province_county IS NULL;
SELECT d.department_name, d.department_id FROM Departments d JOIN Degree_Programs d2 ON d.department_id = d2.department_id ORDER BY d.department_id DESC;
{ "sql": "SELECT DISTINCT D.department_name, D.degree_program_id, D.degree_summary_name, D.degree_summary_description, D.department_id\nFROM Departments D\nJOIN Degree_Programs D2 ON D.department_id = D2.department_id\nJOIN Sections S ON D2.degree_program_id = S.course_id\nJOIN Courses C ON S.course_id = C.course_id\nJOIN Students S2 ON S2.student_id = D2.degree_program_id\nJOIN Student_Enrolment_Courses SC ON S2.student_id = SC.student_course_id\nJOIN Courses C2 ON SC.course_id = C2.course_id\nJOIN Semester_Courses SC2 ON SC2.semester_id = S2.semester_id\nJOIN Courses C3 ON SC2.course_id = C3.course_id\nJOIN Departments D3 ON D3.department_id = D2.department_id\nJOIN Degree_Programs D4 ON D3.department_id = D4.department_id\nJOIN Sections S3 ON D4.degree_program_id = S3.course_id\nJOIN Courses C4 ON S3.course_id = C4.course_id\nJOIN Semester_Courses SC3 ON SC3.semester_id = S3.semester_id\nJOIN Courses C5 ON SC3.course_id = C5.course_id\nJOIN Departments D5 ON D5.department_id = D4.department_id\nJOIN Degree_Programs D6 ON D5.department_id = D6.department_id\nJOIN Sections S6 ON D6.degree_program_id = S6.course_id\nJOIN Courses C6 ON S6.course_id = C6.course_id\nJOIN Semester_Courses SC6 ON SC6.semester_id = S6.semester_id\nJOIN Courses C7 ON SC6.course_id = C7.course_id\nJOIN Departments D7 ON D7.department_id = D6.department_id\nJOIN Degree_Programs D8 ON D7.department_id = D8.department_id\nJOIN Sections S7 ON D8.degree_program_id = S7.course_id\nJOIN Courses C8 ON S7.course_id = C8.course_id\nJOIN Semester_Courses SC7 ON SC7.semester_id = S7.semester_id\nJOIN Courses C9 ON SC7.course_id = C9.course_id\nJOIN Departments D9 ON D9.department_id = D8.department_id\nJOIN Degree_Programs D10 ON D9.department_id = D10.department_id\nJOIN Sections S8 ON D10.degree_program_id = S8.course_id\nJOIN Courses C10 ON S8.course_id = C10.course_id\nJOIN Semester_Courses SC8 ON SC8.semester_id = S8.semester_id\nJOIN Courses C11 ON SC8.course_id = C11.course_id\nJOIN Departments D11 ON D11.department_id = D10.department_id\nJOIN Degree_Programs D12 ON D11.department_id = D12.department_id\nJOIN Sections S9 ON D12.degree_program_id = S9.course_id\nJOIN Courses C12 ON S9.course_id = C12.course_id\nJOIN Semester_Courses SC9 ON SC9.semester_id = S9.semester_id\nJOIN Courses C13 ON SC9.course_id = C13.course_id\nJOIN Departments D13 ON D13.department_id = D12.department_id\nJOIN Degree_Programs D14 ON D13.department_id = D14.department_id\nJOIN Sections S10 ON D14.degree_program_id = S10.course_id\nJOIN Courses C14 ON S10.course_id = C14.course_id\nJOIN Semester_Courses SC10 ON SC10.semester_id = S1
SELECT COUNT(DISTINCT department_id) FROM Departments;
SELECT COUNT(DISTINCT department_id) FROM Departments;
SELECT COUNT(DISTINCT course_name) FROM Courses;
SELECT COUNT(DISTINCT degree_program_id) FROM Degree_Programs;
SELECT COUNT(DISTINCT degree_program_id) FROM Degree_Programs;
SELECT COUNT(*) FROM Departments
SELECT course_name, section_description FROM Sections INNER JOIN Courses ON Sections.course_id = Courses.course_id;
SELECT course_name, section_description FROM Sections JOIN Courses ON Sections.course_id = Courses.course_id;
SELECT course_name, course_id FROM Courses JOIN Sections ON Sections.course_id = Courses.course_id WHERE Sections.section_name IS NULL AND Sections.section_description IS NULL AND Sections.section_description IS NULL;
SELECT course_name, course_id FROM Courses INNER JOIN Sections ON Sections.course_id = Courses.course_id WHERE Sections.section_description LIKE '%less than 2%'
SELECT section_name FROM Sections ORDER BY section_name DESC;
SELECT section_name, section_description, reverse alphabetical order FROM Sections ORDER BY section_name ASC;
SELECT s.first_name, s.student_id FROM Students s JOIN Student_Enrolment_Courses sc ON s.student_id = sc.student_enrolment_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections s2 ON s2.section_id = sc.section_id JOIN Semesters s3 ON s2.semester_id = s3.semester_id JOIN Departments d ON s2.department_id = d.department_id JOIN Degree_Programs dp ON dp.department_id = d.department_id JOIN Transcript_Contents tc ON sc.student_course_id = tc.student_course_id JOIN Transcripts t ON tc.transcript_id = t.transcript_id;
SELECT s.semester_name, s.student_id, s.first_name, s.middle_name, s.last_name FROM Semesters s JOIN Students student ON s.semester_id = student.semester_id JOIN Student_Enrolment_Courses course_enrollments ON student.student_id = course_enrollments.student_enrolment_id JOIN Courses course ON course_enrollments.course_id = course.course_id JOIN Degree_Programs degree_program ON course_enrollments.degree_program_id = degree_program.degree_program_id JOIN Departments department ON degree_program.department_id = department.department_id WHERE s.semester_name = (SELECT semester_name FROM Semesters WHERE semester_id = (SELECT semester_id FROM Semesters WHERE semester_name = 'Undergraduate')) ORDER BY s.semester_name DESC LIMIT 1;
SELECT course_description FROM Courses WHERE course_name LIKE '%computer%'
SELECT DISTINCT address_id, course_name, course_description, section_name, section_description FROM Courses INNER JOIN Sections ON Sections.course_id = Courses.course_id WHERE course_name LIKE 'computer%' OR section_name LIKE 'computer%' OR section_description LIKE 'computer%' OR course_description LIKE 'computer%' OR section_description LIKE 'computer%' OR course_name LIKE 'computer%'
SELECT s.first_name, s.middle_name, s.last_name, s.student_id FROM Students s JOIN Student_Enrolment_Courses sc ON s.student_id = sc.student_course_id JOIN Courses c ON sc.course_id = c.course_id JOIN Departments d ON sc.course_id = d.department_id JOIN Degree_Programs dp ON dp.department_id = d.department_id JOIN Sections s2 ON s.section_id = s2.section_id JOIN Semesters s3 ON s2.semester_id = s3.semester_id JOIN Transcript_Contents tc ON sc.student_course_id = tc.student_course_id JOIN Transcripts t ON tc.transcript_id = t.transcript_id;
SELECT S.first_name, S.middle_name, S.last_name, S.student_id, D.department_id, D.department_name FROM Students S JOIN Degree_Programs D ON S.student_id = D.degree_program_id JOIN Departments ON D.department_id = Departments.department_id WHERE S.date_left IS NULL AND D.degree_summary_name IN ('2 degree programs')
SELECT first_name, middle_name, last_name, other_address_details FROM Students ORDER BY last_name
SELECT DISTINCT middle_name, family_name, first_name FROM Students WHERE degree_program_id IN (SELECT degree_program_id FROM Degree_Programs WHERE degree_summary_name = 'Bachelors') AND semester_id IN (SELECT semester_id FROM Semesters WHERE semester_name = 'Semester 1')
SELECT D.degree_summary_name, COUNT(D.degree_program_id) AS total_students_enrolled FROM Degree_Programs D JOIN Students S ON D.degree_program_id = S.degree_program_id GROUP BY D.degree_summary_name ORDER BY total_students_enrolled DESC;
SELECT DISTINCT D.degree_summary_name, COUNT(D.degree_program_id) AS student_count FROM Degree_Programs D JOIN Departments ON D.department_id = Departments.department_id GROUP BY D.degree_summary_name;
SELECT d.degree_program_id, s.first_name, s.last_name, d.degree_summary_name, d.degree_summary_description FROM Degree_Programs d JOIN Students s ON d.department_id = s.department_id JOIN Degree_Programs ON d.degree_program_id = s.student_id ORDER BY COUNT(s.student_id) DESC LIMIT 1;
SELECT D.Degree_Programs.degree_program_id, D.Degree_Programs.degree_summary_name, D.Degree_Programs.degree_summary_description FROM Degree_Programs D JOIN Students S ON D.Degree_Programs.department_id = S.department_id JOIN Departments D2 ON D.Degree_Programs.department_id = D2.department_id GROUP BY D.Degree_Programs.degree_program_id, D.Degree_Programs.degree_summary_name, D.Degree_Programs.degree_summary_description ORDER BY COUNT(S.S.students) DESC;
SELECT s.student_id, s.first_name, s.middle_name, s.last_name, s.date_first_registered, s.date_left, s.student_enrolment_count, s.undergraduate_id FROM Students s JOIN Student_Enrolment_Courses sc ON s.student_id = sc.student_course_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections ssec ON c.course_id = ssec.course_id JOIN Semesters ssem ON ssec.semester_id = ssem.semester_id JOIN Degree_Programs dp ON ssec.degree_program_id = dp.degree_program_id JOIN Departments d ON dp.department_id = d.department_id GROUP BY s.student_id, s.first_name, s.middle_name, s.last_name, s.date_first_registered, s.date_left, s.undergraduate_id ORDER BY s.date_first_registered DESC;
SELECT s.middle_name, s.id, COUNT(CASE WHEN s.date_left IS NULL THEN 1 ELSE 0 END) AS enrollments FROM Students s JOIN Student_Enrolment_Courses sc ON s.id = sc.student_course_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections s2 ON c.section_id = s2.section_id JOIN Semesters s3 ON s2.semester_id = s3.semester_id JOIN Degree_Programs dp ON dp.degree_program_id = s2.degree_program_id JOIN Departments d ON dp.department_id = d.department_id GROUP BY s.middle_name, s.id
SELECT section_name FROM Sections WHERE section_description IS NULL;
SELECT course_name FROM Courses C INNER JOIN Sections S ON C.course_id = S.course_id WHERE S.section_description IS NULL
SELECT course_name FROM Courses INNER JOIN Student_Enrolment_Courses ON Courses.course_id = Student_Enrolment_Courses.course_id INNER JOIN Courses ON Student_Enrolment_Courses.course_id = Courses.course_id;
SELECT course_name FROM Courses JOIN Departments ON Courses.course_id = Departments.department_id;
SELECT course_name, COUNT(*) AS enrollments FROM Courses GROUP BY course_name HAVING COUNT(*) = (SELECT COUNT(*) FROM Courses) ORDER BY enrollments DESC;
