SELECT S.last_name, S.student_id FROM Students S JOIN Addresses A ON S.current_address_id = A.address_id JOIN Courses C ON S.current_address_id = A.address_id JOIN Sections S2 ON S.current_address_id = S2.section_id JOIN Semester_Semesters S3 ON S2.semester_id = S3.semester_id JOIN Transcripts T ON S2.section_id = T.transcript_id JOIN Transcript_Contents TC ON T.transcript_id = TC.transcript_id JOIN Degree_Programs DP ON DP.department_id = S.department_id JOIN Departments D ON D.department_id = DP.department_id WHERE S.state_province_county = 'North Carolina' AND S.date_left IS NULL;
SELECT s.last_name, s.permanent_address_id, s.state_province_county FROM Addresses s JOIN Students s ON s.address_id = s.permanent_address_id WHERE s.state_province_county = 'North Carolina' AND s.state_province_county IS NULL;
