{ "sql": "SELECT DISTINCT s.student_id, s.date_first_registered, s.date_left, s.first_name, s.middle_name, s.last_name, s.cell_mobile_number, s.email_address, s.ssn FROM Students s JOIN Student_Enrolment_Courses sc ON s.student_id = sc.course_id JOIN Courses c ON sc.course_id = c.course_id JOIN Courses c2 ON c2.course_id = c.course_id JOIN Student_Enrolment_Courses sc2 ON s.student_id = sc2.course_id JOIN Student_Enrolment sc3 ON sc2.student_enrolment_id = sc3.student_enrolment_id JOIN Semesters s2 ON sc3.semester_id = s2.semester_id JOIN Departments d ON sc3.degree_program_id = d.department_id JOIN Degree_Programs dp ON dp.department_id = d.department_id JOIN Transcripts t ON sc3.student_enrolment_id = t.transcript_id JOIN Transcript_Contents tc ON tc.transcript_id = t.transcript_id JOIN Courses c2 ON c2.course_id = c.course_id JOIN Student_Enrolment_Courses sc2 ON s.student_id = sc2.course_id JOIN Student_Enrolment sc3 ON sc3.student_enrolment_id = sc3.student_enrolment_id JOIN Semesters s2 ON sc3.semester_id = s2.semester_id JOIN Departments d ON dp.department_id = d.department_id JOIN Degree_Programs dp ON dp.department_id = d.department_id JOIN Transcripts t ON tc.transcript_id = t.transcript_id JOIN Courses c2 ON c2.course_id = c.course_id JOIN Student_Enrolment_Courses sc2 ON s.student_id = sc2.course_id JOIN Student_Enrolment sc3 ON sc3.student_enrolment_id = sc3.student_enrolment_id JOIN Semesters s2 ON sc3.semester_id = s2.semester_id JOIN Departments d ON dp.department_id = d.department_id JOIN Degree_Programs dp ON dp.department_id = d.department_id JOIN Transcripts t ON tc.transcript_id = t.transcript_id JOIN Courses c2 ON c2.course_id = c.course_id JOIN Student_Enrolment_Courses sc2 ON s.student_id = sc2.course_id JOIN Student_Enrolment sc3 ON sc3.student_enrolment_id = sc3.student_enrolment_id JOIN Semesters s2 ON sc3.semester_id = s2.semester_id JOIN Departments d ON dp.department_id = d.department_id JOIN Degree_Programs dp ON dp.department_id = d.department_id JOIN Transcripts t ON tc.transcript_id = t.transcript_id JOIN Courses c2 ON c2.course_id = c.course_id JOIN Student_Enrolment_Courses sc2 ON s.student_id = sc2.course_id JOIN Student_Enrolment sc3 ON sc3.student_enrolment_id = sc3.student_enrolment_id JOIN Semesters s2 ON sc3.semester_id = s2.semester_id JOIN Departments d ON dp.department_id = d.department_id JOIN Degree_Programs dp ON dp.department_id = d.department_id JOIN Transcripts t ON tc.transcript_id = t.transcript_id JOIN Courses c2 ON c2.course_id = c.course_id JOIN Student_Enrolment_Courses sc2 ON s.student_id = sc2.course_id JOIN Student_Enrolment sc3 ON sc3.student_enrolment_id = sc3.student_enrolment_id JOIN Semesters s2 ON sc3.semester_id = s2.semester_id JOIN Departments d ON dp.department_id = d.department_id JOIN Degree_Programs dp ON dp.department_id = d.department_id JOIN Transcripts t ON tc.transcript
SELECT s.last_name, s.cell_mobile_number FROM Students s WHERE s.last_name = 'Timmothy' AND s.middle_name = 'Ward'
SELECT student_id, cell_mobile_number, first_name, last_name, other_student_details FROM Students WHERE first_name = 'Timothy' AND last_name = 'Ward';
SELECT s.first_name, s.middle_name, s.last_name, s.date_first_registered FROM Students s WHERE s.date_first_registered IS NOT NULL ORDER BY s.date_first_registered ASC;
SELECT S.middle_name, S.family_name, S.first_name FROM Students S;
SELECT s.first_name, s.middle_name, s.last_name, s.date_first_registered, s.date_left FROM Students s JOIN Student_Enrolment_Courses sc ON s.student_id = sc.student_enrolment_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections ssec ON sc.course_id = ssec.course_id JOIN Semesters ssem ON ssec.semester_id = ssem.semester_id JOIN Degree_Programs dp ON ssec.degree_program_id = dp.degree_program_id JOIN Departments d ON dp.department_id = d.department_id WHERE s.date_first_registered < s.date_left ORDER BY s.date_first_registered ASC;
SELECT s.middle_name, s.family_name, s.first_name FROM Students s JOIN Addresses a ON s.current_address_id = a.address_id JOIN Transcripts t ON s.student_id = t.student_id JOIN Transcript_Contents tc ON t.transcript_id = tc.transcript_id WHERE t.transcript_date = (SELECT MIN(transcript_date) FROM Transcripts t1 WHERE t1.transcript_date IS NOT NULL)
SELECT s.last_name, s.first_name FROM Students s JOIN Addresses a ON s.current_address_id = a.address_id WHERE s.last_name != s.first_name;
SELECT s.first_name, s.middle_name, s.last_name FROM Students s WHERE s.permanent_address_id != s.current_address_id;
SELECT DISTINCT s.place_id, s.lines AS line FROM Addresses s JOIN Student_Enrolment_Courses sc ON s.address_id = sc.student_enrolment_id JOIN Courses c ON sc.course_id = c.course_id JOIN Sections ssec ON c.course_id = ssec.course_id JOIN Departments d ON ssec.department_id = d.department_id JOIN Degree_Programs dp ON d.department_id = dp.department_id JOIN Transcripts t ON dp.degree_program_id = t.transcript_id JOIN Transcript_Contents tc ON t.transcript_id = tc.transcript_id JOIN Courses c ON tc.student_course_id = c.course_id JOIN Student_Enrolment_Courses sc ON tc.student_course_id = sc.student_course_id JOIN Student_Enrolment s_e ON sc.student_enrolment_id = s_e.student_enrolment_id JOIN Semesters s_sem ON s_e.semester_id = s_sem.semester_id JOIN Students s_st ON s_e.student_id = s_st.student_id GROUP BY s.place_id, s.lines;
SELECT S.id, A.line_1, A.line_2 FROM Addresses A JOIN Students S ON A.address_id = S.current_address_id WHERE A.state_province_county IS NULL ORDER BY S.id DESC LIMIT 1;
SELECT AVG(transcript_date) FROM Transcripts;
SELECT AVG(date_left) FROM Students;
SELECT s.date_left, s.first_name, s.middle_name, s.last_name, s.cell_mobile_number, s.email_address, s.ssn, s.date_first_registered, s.date_left, s.other_student_details FROM Students s JOIN Addresses ON s.current_address_id = Addresses.address_id JOIN Transcripts ON s.date_left = Transcripts.transcript_date
SELECT MIN(transcript_date) AS earliest_date FROM Transcripts;
SELECT COUNT(*) FROM Addresses;
SELECT COUNT(*) FROM Students;
SELECT MAX(transcript_date) FROM Transcripts;
SELECT MAX(transcript_date) AS last_student_record_release_date FROM Transcripts;
SELECT DISTINCT student_enrolment_id, course_id, degree_program_id FROM Student_Enrolment_Courses JOIN Student_Enrolment ON Student_Enrolment_Courses.student_enrolment_id = Student_Enrolment.student_id;
SELECT MAX(course_id), MAX(Enrolment.id) FROM Student_Enrolment_Courses INNER JOIN Student_Enrolment ON Student_Enrolment_Courses.student_enrolment_id = Student_Enrolment.student_id GROUP BY course_id;
SELECT student_id, date_first_registered, date_left FROM Students ORDER BY date_first_registered ASC LIMIT 1;
SELECT student_id, date_first_registered, date_left, student_id FROM Students ORDER BY date_first_registered ASC LIMIT 1;
SELECT DISTINCT semester_name FROM Semesters INNER JOIN Student_Enrolment ON Student_Enrolment.semester_id = Semesters.semester_id INNER JOIN Students ON Students.student_id = Student_Enrolment.student_id INNER JOIN Addresses ON Addresses.address_id = Students.current_address_id INNER JOIN Departments ON Departments.department_id = Student_Enrolment.degree_program_id INNER JOIN Degree_Programs ON Degree_Programs.department_id = Departments.department_id WHERE Student_Enrolment_Courses.course_id IN (SELECT course_id FROM Courses WHERE course_name IN ('Master', 'Bachelor'))
SELECT S.student_id FROM Students S JOIN Student_Enrolment_Courses SC ON S.student_id = SC.student_course_id JOIN Courses C ON SC.course_id = C.course_id JOIN Sections S1 ON S.section_id = S1.section_id JOIN Departments D ON S1.department_id = D.department_id JOIN Degree_Programs D1 ON D1.department_id = D.department_id JOIN Transcripts T ON T.transcript_id = SC.transcript_id JOIN Transcript_Contents TC ON TC.student_course_id = SC.student_course_id JOIN Courses C1 ON TC.course_id = C1.course_id
SELECT COUNT(DISTINCT address_id) FROM Addresses;
SELECT DISTINCT Addresses.address_id, Addresses.line_1, Addresses.line_2, Addresses.line_3, Addresses.city, Addresses.zip_postcode, Addresses.state_province_county, Addresses.country, Addresses.other_address_details FROM Addresses WHERE Addresses.address_id IN (SELECT permanent_address_id FROM Students) UNION ALL SELECT Addresses.address_id, Addresses.line_1, Addresses.line_2, Addresses.line_3, Addresses.city, Addresses.zip_postcode, Addresses.state_province_county, Addresses.country, Addresses.other_address_details FROM Addresses WHERE Addresses.address_id IN (SELECT current_address_id FROM Students)
SELECT s.first_name, s.last_name, s.cell_mobile_number, s.email_address, s.ssn, s.date_first_registered, s.date_left, s.other_student_details FROM Students s ORDER BY s.date_first_registered DESC LIMIT 100;
SELECT s.first_name, s.middle_name, s.last_name, s.cell_mobile_number, s.email_address, s.ssn, s.date_first_registered, s.date_left, s.other_student_details FROM Students s ORDER BY s.first_name DESC;
SELECT DISTINCT course_name, section_name, section_description FROM Sections JOIN Courses ON Sections.course_id = Courses.course_id JOIN Degree_Programs ON Sections.course_id = Degree_Programs.department_id WHERE section_name = 'h';
SELECT course_description FROM Courses WHERE section_name = 'h'
SELECT s.last_name, s.cell_mobile_number FROM Students s JOIN Addresses a ON s.permanent_address_id = a.address_id WHERE a.country = 'Haiti' OR s.cell_mobile_number = '09700166582'
SELECT s.first_name, s.last_name FROM Students s JOIN Addresses a ON s.permanent_address_id = a.address_id WHERE a.country = 'Haiti' OR s.cell_mobile_number = '09700166582'
SELECT Title FROM Cartoon ORDER BY Title ASC
SELECT Title FROM Cartoon ORDER BY Title ASC;
SELECT TV_series.id, TV_series.Series_name, TV_series.Channel FROM TV_series JOIN TV_Channel ON TV_series.Channel = TV_Channel.id WHERE TV_series.Director = 'Ben Jones';
SELECT Title FROM Cartoon WHERE Directed_by = 'Ben Jones'
SELECT COUNT(*) FROM Cartoon WHERE Written_by = 'Joseph Kuhr'
SELECT COUNT(*) AS animations_written_by_joseph_kuhr FROM Cartoon INNER JOIN TV_Channel ON Cartoon.Channel = TV_Channel.id WHERE Cartoon.Written_by = 'Joseph Kuhr' AND Cartoon.Directed_by = 'Joseph Kuhr'
SELECT Title, Directed_by FROM Cartoon ORDER BY Air_Date;
SELECT Title, Directed_by FROM Cartoon ORDER BY Air_Date;
SELECT Title FROM Cartoon WHERE Directed_by = 'Ben Jones' OR Directed_by = 'Brandon Vietti';
SELECT Title FROM Cartoon WHERE Directed_by = 'Ben Jones' OR Directed_by = 'Brandon Vietti' AND Title IS NOT NULL
SELECT Country, COUNT(TV_Channel.id) AS TV_channels_count FROM TV_Channel JOIN TV_series ON TV_Channel.Channel = TV_series.Channel GROUP BY Country ORDER BY TV_channels_count DESC;
SELECT TV_Channel.Country, COUNT(TV_Channel.Channel) AS Total_Channels FROM TV_Channel JOIN TV_series ON TV_series.Channel = TV_Channel.id GROUP BY TV_Channel.Country ORDER BY COUNT(TV_Channel.Channel) DESC LIMIT 1;
SELECT COUNT(DISTINCT series_name) AS series_name_count, COUNT(DISTINCT Content) AS content_count FROM TV_Channel;
SELECT COUNT(DISTINCT TV_Channel.Content) AS Content_count, COUNT(DISTINCT TV_Channel.Serial) AS Serial_count FROM TV_Channel;
SELECT Content FROM TV_Channel WHERE series_name = 'Sky Radio'
SELECT Content FROM TV_series JOIN TV_Channel ON TV_series.Channel = TV_Channel.id;
SELECT TV_Channel.Package_Option FROM TV_Channel WHERE TV_series.Series_name = 'Sky Radio'
SELECT TV_Channel.Package_Option FROM TV_Channel INNER JOIN TV_series ON TV_Channel.Channel = TV_series.Channel WHERE TV_series.Series_name = 'Sky Radio' AND TV_Channel.Country IS NULL;
SELECT COUNT(*) FROM TV_Channel WHERE Language = 'English' AND Content IS NOT NULL;
SELECT COUNT(*) FROM TV_Channel WHERE Language = 'English' AND Channel IS NOT NULL;
SELECT Language, COUNT(*) AS TV_Channel_count FROM TV_series JOIN TV_Channel ON TV_series.Channel = TV_Channel.id GROUP BY Language ORDER BY TV_Channel_count DESC LIMIT 1
SELECT Language, COUNT(Channel) AS Channels_used FROM TV_Channel JOIN TV_series ON TV_Channel.id = TV_series.Channel GROUP BY Language ORDER BY COUNT(Channel) DESC LIMIT 1
SELECT Language, COUNT(Country) AS Channel_Count FROM TV_Channel GROUP BY Language
SELECT Language, COUNT(TV_Channel.id) AS TV_Channels_used_per_language FROM TV_Channel JOIN TV_series ON TV_Channel.Channel = TV_series.Channel GROUP BY Language
SELECT TV_Channel.Channel, TV_series.Series_name FROM TV_Channel INNER JOIN TV_series ON TV_Channel.id = TV_series.Channel;
SELECT TV_Channel.id, TV_Channel.series_name FROM TV_Channel JOIN TV_series ON TV_Channel.Channel = TV_series.Channel JOIN Cartoon ON TV_series.Channel = Cartoon.Channel WHERE Cartoon.Title = 'The Rise of the Blue Beetle' ORDER BY TV_Channel.id;
SELECT TV_series.Title AS animation_name, TV_Channel.Series_name AS series_name FROM TV_series INNER JOIN TV_Channel ON TV_series.Channel = TV_Channel.id WHERE TV_Channel.Series_name = 'Sky Radio'
SELECT Title FROM Cartoon JOIN TV_series ON Cartoon.Channel = TV_series.Channel WHERE TV_series.Series_name = 'Sky Radio' AND Title IS NOT NULL
SELECT TV_series.Episode, TV_series.Rating FROM TV_series JOIN TV_channel ON TV_series.Channel = TV_channel.id ORDER BY TV_series.Rating DESC;
SELECT Episode FROM TV_series ORDER BY Rating
SELECT TV_series.Episode, TV_series.Rating, TV_series.Channel FROM TV_series JOIN TV_Channel ON TV_series.Channel = TV_Channel.id WHERE TV_series.Rating ORDER BY Rating DESC LIMIT 3;
SELECT Episode, Rating, Share FROM TV_series WHERE Episode IS NOT NULL AND Rating IS NOT NULL AND Share IS NOT NULL ORDER BY Rating DESC LIMIT 3;
SELECT MAX(18_49_Rating_Share), MIN(18_49_Rating_Share) FROM TV_series;
SELECT MAX(Pay_per_view_PPV), MIN(Pay_per_view_PPV) FROM TV_series;
SELECT TV_series.Air_Date FROM TV_series JOIN Cartoon ON TV_series.Episode = Cartoon.Original_air_date WHERE Cartoon.Title = 'A Love of a Lifetime'
SELECT Air_Date FROM TV_series JOIN TV_Channel ON TV_series.Channel = TV_Channel.id WHERE Title = 'A Love of a Lifetime'
SELECT TV_series.Weekly_Rank FROM TV_series JOIN TV_Channel ON TV_series.Channel = TV_Channel.id WHERE TV_series.Episode = 'A Love of a Lifetime'
SELECT TV_series.Weekly_Rank AS score_per_week FROM TV_series JOIN TV_Channel ON TV_series.Channel = TV_Channel.id WHERE TV_series.Series_name = 'A Love of a Lifetime'
SELECT TV_series.Series_name FROM TV_series INNER JOIN TV_Channel ON TV_series.Channel = TV_Channel.id WHERE TV_series.Episode = 'A Love of a Lifetime' AND TV_series.Episode IS NOT NULL;
SELECT TV_series.Series_name FROM TV_series JOIN TV_Channel ON TV_series.Channel = TV_Channel.id WHERE TV_series.Episode = 'A Love of a Lifetime' AND TV_series.Series_name IS NOT NULL;
SELECT TV_series.Episode FROM TV_series JOIN TV_Channel ON TV_series.Channel = TV_Channel.id WHERE TV_series.series_name = 'Sky Radio'
SELECT TV_series.Episode FROM TV_series JOIN TV_Channel ON TV_series.Channel = TV_Channel.id WHERE TV_series.Series_name = 'Sky Radio'
SELECT COUNT(*) AS total_animations_directed_by_director FROM TV_series INNER JOIN Cartoon ON TV_series.id = Cartoon.id JOIN TV_Channel ON TV_series.Channel = TV_Channel.id GROUP BY Directed_by
SELECT COUNT(DISTINCT Cartoon.Directing_by) AS number_of_animations_per_director
SELECT Cartoon.id, TV_Channel.Channel FROM TV_series JOIN TV_Channel ON TV_series.Channel = TV_Channel.id JOIN Cartoon ON TV_series.id = Cartoon.id WHERE Cartoon.Production_code = (SELECT MAX(Production_code) FROM Cartoon) ORDER BY Cartoon.id ASC;
SELECT TV_Channel.id, TV_Channel.Channel AS channel FROM TV_Channel JOIN TV_series ON TV_Channel.id = TV_series.Channel JOIN Cartoon ON TV_series.id = Cartoon.id ORDER BY Cartoon.Original_air_date DESC;
SELECT TV_Channel.Package_Option, TV_Channel.series_name FROM TV_Channel JOIN TV_series ON TV_Channel.Channel = TV_series.Channel;
SELECT TV_Channel.Package_Option, TV_Channel.Series_name, TV_Channel.Channel FROM TV_Channel JOIN TV_series ON TV_Channel.Channel = TV_series.Channel WHERE TV_Channel.Language = 'HD TV'
SELECT C.Country, C.Written_by, C.Content FROM TV_Channel C JOIN TV_series T ON C.Channel = T.Channel JOIN Cartoon C2 ON C.Channel = C2.Channel JOIN TV_series T2 ON C2.Series = T2.Series WHERE C.Written_by = 'Todd Casey' AND C.Content LIKE '%animation%'
SELECT TV_Channel.Country, TV_series.Series_name FROM TV_Channel JOIN TV_series ON TV_Channel.Channel = TV_series.Channel WHERE TV_series.Written_by = 'Todd Casey' AND TV_series.Channel IS NOT NULL;
SELECT Country FROM TV_Channel JOIN Cartoon ON TV_Channel.id = Cartoon.Channel WHERE Content IS NOT NULL AND Content LIKE '%animation%' AND Written_by = 'Todd Casey'
SELECT Country FROM TV_Channel WHERE Channel = (SELECT Channel FROM TV_series WHERE Series_name = 'Todd Casey' AND 18_49_Rating_Share = '18_49' AND Pay_per_view_PPV = '49' AND Weekly_Rank = '49')
SELECT TV_Channel.id, TV_Channel.Series, TV_Channel.Country, TV_Channel.Language, TV_Channel.Content, TV_Channel.Pixel_aspect_ratio_PAR, TV_Channel.Hight_definition_TV, TV_Channel.Pay_per_view_PPV, TV_Channel.Package_Option FROM TV_Channel JOIN TV_series ON TV_Channel.id = TV_series.Channel JOIN Cartoon ON TV_series.id = Cartoon.id WHERE Cartoon.Directed_by = 'Ben Jones' OR Cartoon.Directed_by = 'Michael Chang'
SELECT TV_Channel.id, TV_Channel.series_name, TV_Channel.Country, TV_Channel.Language, TV_Channel.Content, TV_Channel.Pixel_aspect_ratio_PAR, TV_Channel.Hight_definition_TV, TV_Channel.Pay_per_view_PPV, TV_Channel.Package_Option FROM TV_Channel JOIN TV_series ON TV_Channel.id = TV_series.Channel JOIN Cartoon ON TV_Channel.id = Cartoon.Channel WHERE Cartoon.Directed_by IN ('Ben Jones', 'Michael Chang')
SELECT TV_Channel.Country, TV_Channel.Pixel_aspect_ratio_PAR FROM TV_Channel JOIN TV_series ON TV_Channel.Channel = TV_series.Channel WHERE TV_series.Language != 'English'
