SELECT countrylanguage.Language AS Language, country.CountryCode AS CountryCode FROM countrylanguage INNER JOIN country ON countrylanguage.CountryCode = country.Code WHERE country.CountryCode NOT IN ('US', 'BE', 'CA', 'CH', 'FR', 'DE', 'GB', 'IN', 'JP', 'MX', 'NL', 'PT', 'RU', 'SE', 'SI', 'TR', 'TN', 'TH', 'TW', 'YT') AND country.CountryCode NOT IN ('US', 'BE', 'CA', 'CH', 'FR', 'DE', 'GB', 'IN', 'JP', 'MX', 'NL', 'PT', 'RU', 'SE', 'SI', 'TR', 'TN', 'TH', 'TW', 'YT')
SELECT city.Name, countrylanguage.Language FROM city JOIN countrylanguage ON city.CountryCode = countrylanguage.CountryCode WHERE countrylanguage.IsOfficial = FALSE
SELECT Name FROM city JOIN country ON city.CountryCode = country.Code WHERE country.Continent = 'Europe' AND countrylanguage.IsOfficial = FALSE
SELECT DISTINCT Name FROM city JOIN countrylanguage ON city.CountryCode = countrylanguage.CountryCode WHERE Language = 'Chinese' AND CountryCode IN ('ASIAN STATES')
SELECT DISTINCT Name FROM city INNER JOIN country ON city.CountryCode = country.Code WHERE country.Continent = 'Asia' AND country.Language.IsOfficial = '1'
SELECT Name, founded_year, territory FROM country WHERE Population = (SELECT MIN(Population) FROM city)
SELECT Name, IndepYear, Territory FROM country WHERE Population < (SELECT MIN(Population) FROM country)
SELECT COUNT(DISTINCT Name), Name, CountryCode AS Leader FROM city JOIN country ON city.CountryCode = country.Code GROUP BY Name, CountryCode ORDER BY Population DESC LIMIT 1;
SELECT Country.Name, COUNT(DISTINCT City.District) AS TerritoryCount, Country.HeadOfState FROM city JOIN country ON city.CountryCode = country.Code WHERE country.CountryCode = (SELECT CountryCode FROM country WHERE Country.Name = (SELECT Name FROM country WHERE Country.Name = 'Country' and Country.Region = 'Territory') LIMIT 1) GROUP BY Country.Name, Country.HeadOfState
SELECT c.Name, c.CountryCode FROM city c JOIN countrylanguage cl ON c.CountryCode = cl.CountryCode WHERE cl.IsOfficial = TRUE AND cl.Percentage > 0 AND cl.Language IS NOT NULL;
SELECT c.Name, c.CountryCode, l.Language, l.IsOfficial, l.Percentage FROM city c JOIN countrylanguage l ON c.CountryCode = l.CountryCode WHERE l.IsOfficial = 1 AND l.Percentage > 0 ORDER BY l.Language;
SELECT COUNT(DISTINCT District) AS Districts, COUNT(DISTINCT Population) AS Residents FROM city WHERE Population > (SELECT AVG(Population) FROM city)
SELECT COUNT(DISTINCT district), COUNT(DISTINCT population) FROM city WHERE Population > (SELECT AVG(Population) FROM city)
SELECT country.Name, COUNT(DISTINCT country.Name) AS total_residents FROM country JOIN city ON country.Code = city.CountryCode WHERE country.LifeExpectancy > 72 GROUP BY country.Name
SELECT country.GovernmentForm, COUNT(DISTINCT city.Population) AS total_residents FROM city JOIN country ON city.CountryCode = country.Code WHERE country.GovernmentForm IS NOT NULL AND country.LifeExpectancy > 72 GROUP BY country.GovernmentForm
SELECT c.Continent, AVG(c.LifeExpectancy) AS average_lifespan, COUNT(c.CountryCode) AS total_people FROM country c JOIN city d ON c.Code = d.CountryCode WHERE c.LifeExpectancy < 72 GROUP BY c.Continent
SELECT c.Continent, COUNT(c.CountryCode) AS total_people, AVG(c.LifeExpectancy) AS average_lifespan FROM country c JOIN city ON c.CountryCode = city.CountryCode WHERE c.LifeExpectancy < 72;
SELECT Name, District FROM city JOIN country ON city.CountryCode = country.Code WHERE country.Region = 'Top 5' AND District IS NOT NULL;
SELECT CountryName, CountryCode FROM country ORDER BY Population DESC LIMIT 5;
SELECT CountryName, Population FROM country ORDER BY Population DESC LIMIT 3;
SELECT Name, Population FROM country ORDER BY Population DESC LIMIT 3
SELECT CountryName FROM country ORDER BY Population ASC LIMIT 3;
SELECT DISTINCT CountryName FROM city INNER JOIN country ON city.CountryCode = country.Code WHERE Population < (SELECT MIN(Population) FROM city)
SELECT COUNT(*) FROM country WHERE Continent = 'Asia'
SELECT COUNT(*) FROM country WHERE Continent = 'Asia'
SELECT Name FROM country WHERE Continent = 'Europe' AND Population = 80000;
SELECT CountryName FROM country WHERE Continent = 'Europe' AND Population = 80000;
SELECT COUNT(DISTINCT city.Population) AS total_people, AVG(country.SurfaceArea) AS average_territory FROM city JOIN country ON city.CountryCode = country.Code WHERE country.Continent = 'North America' AND country.SurfaceArea > 3000;
SELECT COUNT(*) AS total_people, AVG(SurfaceArea) AS average_territory FROM city c JOIN country g ON c.CountryCode = g.Code WHERE g.Continent = 'North America' AND g.SurfaceArea > 3000;
SELECT Name FROM city WHERE Population BETWEEN 160000 AND 900000;
SELECT Name FROM city WHERE Population BETWEEN 160000 AND 900000
SELECT country.Name, countrylanguage.Language, countrylanguage.IsOfficial, countrylanguage.Percentage FROM countrylanguage INNER JOIN country ON countrylanguage.CountryCode = country.Code WHERE countrylanguage.IsOfficial = 1 AND countrylanguage.Percentage = (SELECT MAX(Percentage) FROM countrylanguage WHERE countrylanguage.IsOfficial = 1)
SELECT countrylanguage.Language, COUNT(*) AS NationCount FROM countrylanguage JOIN country ON countrylanguage.CountryCode = country.Code GROUP BY countrylanguage.CountryCode ORDER BY NationCount DESC;
SELECT CountryCode, Language, COUNT(*) AS MostPeoplePerState FROM countrylanguage JOIN country ON country.Code = countrylanguage.CountryCode GROUP BY CountryCode, Language ORDER BY COUNT(*) DESC;
SELECT country.Code AS country_code, language.Language AS language, COUNT(language.Language) AS most_people_spoken_languages FROM countrylanguage JOIN country ON country.Code = countrylanguage.CountryCode GROUP BY country.Code, language.Language;
SELECT COUNT(*) FROM countrylanguage WHERE Language = 'Spanish' AND Percentage IS NOT NULL;
SELECT COUNT(DISTINCT countrylanguage.CountryCode) FROM countrylanguage WHERE Language = 'Spanish'
SELECT country.Code, country.Name, country.Continent, country.Region, country.SurfaceArea, country.IndepYear, country.Population, country.LifeExpectancy, country.GNP, country.GNPOld, country.LocalName, country.GovernmentForm, country.Capital, countrylanguage.Language FROM country INNER JOIN countrylanguage ON country.Code = countrylanguage.CountryCode WHERE countrylanguage.IsOfficial = TRUE ORDER BY countrylanguage.Percentage DESC LIMIT 1;
SELECT countrylanguage.CountryCode FROM countrylanguage JOIN country ON countrylanguage.CountryCode = country.Code WHERE Language = 'Spanish' AND countrylanguage.IsOfficial = TRUE;
SELECT COUNT(*) AS Directors_count FROM conductor;
SELECT COUNT(*) AS directors_count FROM conductor;
SELECT Name, Age FROM conductor ORDER BY Age ASC;
SELECT Name, Age FROM conductor ORDER BY Age;
SELECT Name FROM conductor WHERE Nationality != 'USA'
SELECT conductor.Name FROM conductor WHERE conductor.Nationality != 'USA'
SELECT o.Orchestra, p.Year_of_Founded, p.Weekly_rank FROM orchestra o JOIN performance p ON o.Orchestra_ID = p.Orchestra_ID ORDER BY p.Year_of_Founded DESC;
SELECT orchestra.Orchestra_ID, orchestra.Record_Company, orchestra.Year_of_Founded, performance.Weekly_rank, performance.Share, performance.Type, performance.Date, performance.Official_ratings_(millions) FROM orchestra JOIN performance ON orchestra.Orchestra_ID = performance.Orchestra_ID ORDER BY orchestra.Year_of_Founded DESC;
SELECT AVG(show.Attendance) AS Average_guest_of_shows FROM show;
SELECT AVG(Show.Attendance) AS average_guest FROM show JOIN performance ON show.Performance_ID = performance.Performance_ID JOIN conductor ON performance.Orchestra_ID = conductor.Conductor_ID;
SELECT MAX(Share), MIN(Share) FROM performance WHERE Type != 'Live final'
SELECT MAX(Share), MIN(Share) FROM performance INNER JOIN show ON performance.Performance_ID = show.Performance_ID WHERE show.Type != 'Live final'
SELECT COUNT(DISTINCT conductor.Nationality) FROM conductor;
SELECT COUNT(DISTINCT conductor.Nationality) FROM conductor;
SELECT Name, Year_of_Work FROM conductor ORDER BY Year_of_Work DESC
SELECT Name, Year_of_Work FROM conductor ORDER BY Year_of_Work DESC;
SELECT conductor.Name, conductor.Age, conductor.Nationality, conductor.Year_of_Work FROM conductor JOIN performance ON conductor.Conductor_ID = performance.Orchestra_ID JOIN orchestra ON orchestra.Orchestra_ID = performance.Orchestra_ID GROUP BY conductor.Name ORDER BY conductor.Age DESC LIMIT 1
SELECT conductor.Name, conductor.Age, conductor.Nationality, conductor.Conductor_ID FROM conductor JOIN performance ON conductor.Conductor_ID = performance.Conductor_ID JOIN orchestra ON orchestra.Conductor_ID = performance.Orchestra_ID GROUP BY conductor.Conductor_ID ORDER BY conductor.Age DESC;
SELECT conductor.Name, orchestra.Orchestra FROM conductor INNER JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID;
SELECT conductor.Name, orchestra.Orchestra, conductor.Conductor_ID, orchestra.Record_Company, conductor.Age, conductor.Nationality, orchestra.Year_of_Founded, orchestra.Major_Record_Format FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID ORDER BY conductor.Age;
SELECT conductor.Name FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID JOIN performance ON orchestra.Orchestra_ID = performance.Orchestra_ID JOIN show ON performance.Performance_ID = show.Performance_ID WHERE show.If_first_show = '1' AND show.Attendance IS NOT NULL;
SELECT Name, Year_of_Founded FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID JOIN performance ON performance.Orchestra_ID = orchestra.Orchestra_ID JOIN show ON show.Performance_ID = performance.Performance_ID GROUP BY conductor.Name, orchestra.Orchestra_ID, show.Show_ID HAVING COUNT(Show_ID) > 1;
SELECT conductor.Name, orchestra.Orchestra, conductor.Conductor_ID, orchestra.Record_Company, conductor.Age, conductor.Nationality, orchestra.Year_of_Founded, performance.Weekly_rank, performance.Official_ratings_(millions) FROM conductor INNER JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID ORDER BY conductor.Weekly_rank DESC;
SELECT conductor.Name, orchestra.Orchestra, conductor.Age, conductor.Nationality, conductor.Year_of_Work, orchestra.Record_Company, orchestra.Found Year_of_Founded, performance.Weekly_rank, show.Result, show.Attendance FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID JOIN performance ON orchestra.Orchestra_ID = performance.Orchestra_ID JOIN show ON performance.Performance_ID = show.Performance_ID WHERE conductor.Year_of_Work IS NOT NULL ORDER BY conductor.Weekly_rank DESC LIMIT 1;
SELECT conductor.Name FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID WHERE orchestra.Year_of_Founded > 2008;
SELECT conductor.Name, orchestra.Orchestra, conductor.Age, conductor.Nationality, orchestra.Year_of_Founded, orchestra.Record_Company FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID WHERE orchestra.Year_of_Founded > 2008;
SELECT conductor.Name, orchestra.Orchestra_ID FROM conductor INNER JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID;
SELECT COUNT(*) AS total_ensembles, COUNT(DISTINCT enterprise_id) AS unique_ensembles FROM enterprise JOIN conductor ON conductor.Conductor_ID = enterprise.Conductor_ID JOIN orchestra ON orchestra.Orchestra_ID = conductor.Orchestra_ID JOIN performance ON performance.Orchestra_ID = orchestra.Orchestra_ID JOIN show ON show.Performance_ID = performance.Performance_ID;
SELECT orchestra.Orchestra, COUNT(orchestra.Orchestra) AS count FROM orchestra JOIN conductor ON orchestra.Conductor_ID = conductor.Conductor_ID GROUP BY orchestra.Orchestra ORDER BY count ASC;
SELECT Major_Record_Format, COUNT(*) AS Frequency FROM orchestra GROUP BY Major_Record_Format ORDER BY Frequency
SELECT orchestra.Orchestra, COUNT(performances.Performance_ID) AS total_shares FROM performance INNER JOIN orchestra ON performance.Orchestra_ID = orchestra.Orchestra_ID GROUP BY orchestra.Orchestra_ID ORDER BY total_shares DESC;
SELECT COUNT(*) AS total_ensembles, conductor.Name AS enterprise FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID GROUP BY conductor.Name ORDER BY COUNT(*) DESC LIMIT 1
SELECT orchestra.Orchestra FROM orchestra JOIN conductor ON orchestra.Conductor_ID = conductor.Conductor_ID WHERE conductor.Age IS NULL;
SELECT orchestra.Orchestra_ID FROM orchestra JOIN conductor ON orchestra.Conductor_ID = conductor.Conductor_ID WHERE conductor.Age IS NULL
SELECT p.Share, o.Orchestra, o.Year_of_Founded FROM performance p JOIN orchestra o ON p.Orchestra_ID = o.Orchestra_ID WHERE p.Year_of_Founded < 2003 OR p.Year_of_Founded > 2003;
SELECT DISTINCT conductor.Conductor_ID, orchestra.Orchestra_ID, performance.Performance_ID, show.Show_ID FROM conductor JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID JOIN performance ON orchestra.Orchestra_ID = performance.Orchestra_ID JOIN show ON performance.Performance_ID = show.Performance_ID WHERE conductor.Age < 2003 OR conductor.Age > 2003;
SELECT COUNT(*) FROM orchestra INNER JOIN performance ON orchestra.Orchestra = performance.Orchestra_ID WHERE performance.Type IN ('CD', 'DVD')
SELECT COUNT(*) FROM orchestra WHERE orchestra.Record_Company = 'CD' OR orchestra.Record_Company = 'DVD' AND orchestra.Conductor_ID IS NOT NULL;
SELECT DISTINCT Year_of_Founded FROM orchestra JOIN conductor ON orchestra.Conductor_ID = conductor.Conductor_ID WHERE orchestra.Record_Company IS NOT NULL AND orchestra.Major_Record_Format IS NOT NULL;
SELECT o.Year_of_Founded, p.Type, p.Date FROM orchestra o JOIN performance p ON o.Conductor_ID = p.Conductor_ID WHERE p.Weekly_rank > 1000000 AND o.Major_Record_Format = 'millions'
