SELECT DISTINCT grade FROM Highschooler WHERE ID IN (SELECT student_id FROM Friend JOIN Likes ON Friend.friend_id = Likes.student_id GROUP BY student_id HAVING COUNT(*) >= 4)
SELECT Highschooler.ID, Friend.friend_id FROM Highschooler INNER JOIN Friend ON Highschooler.ID = Friend.friend_id;
SELECT COUNT(DISTINCT student_id) FROM Highschooler JOIN Friend ON Highschooler.ID = Friend.student_id;
SELECT Highschooler.name, COUNT(Friend.friend_id) AS friend_count FROM Highschooler JOIN Friend ON Highschooler.ID = Friend.friend_id GROUP BY Highschooler.name;
SELECT name, COUNT(*) AS friends FROM Highschooler JOIN Friend ON Highschooler.ID = Friend.student_id GROUP BY name;
SELECT name FROM Highschooler JOIN Friend ON Highschooler.ID = Friend.student_id GROUP BY name ORDER BY COUNT(Friend.friend_id) DESC LIMIT 1
SELECT name FROM Highschooler JOIN Friend ON Highschooler.ID = Friend.student_id GROUP BY name ORDER BY COUNT(Friend.friend_id) DESC LIMIT 1
SELECT name FROM Highschooler WHERE name IN (SELECT name FROM (SELECT student_id, name FROM Highschooler JOIN Friend ON Highschooler.ID = Friend.student_id GROUP BY student_id HAVING COUNT(Friend.friend_id) >= 3))
SELECT name FROM Highschooler WHERE ID IN (SELECT student_id FROM Friend WHERE (SELECT COUNT(*) FROM Highschooler WHERE ID = student_id GROUP BY ID HAVING COUNT(*) >= 3))
SELECT DISTINCT Highschooler.name FROM Highschooler JOIN Friend ON Highschooler.ID = Friend.friend_id WHERE Friend.student_id = 1000;
SELECT DISTINCT name FROM Highschooler INNER JOIN Friend ON Highschooler.ID = Friend.friend_id WHERE Friend.student_id = (SELECT ID FROM Highschooler WHERE name = 'Kyle') LIMIT 1;
SELECT COUNT(DISTINCT Highschooler.ID) FROM Highschooler;
SELECT COUNT(DISTINCT Highschooler.ID) FROM Highschooler JOIN Friend ON Highschooler.ID = Friend.friend_id JOIN Likes ON Highschooler.ID = Likes.student_id WHERE Highschooler.name = 'Kyle'
SELECT Highschooler.ID FROM Highschooler WHERE Highschooler.ID NOT IN (SELECT Friend.student_id FROM Friend)
SELECT DISTINCT Highschooler.ID FROM Highschooler WHERE Highschooler.ID NOT IN (SELECT Friend.student_id FROM Friend)
SELECT name FROM Highschooler WHERE ID NOT IN (SELECT student_id FROM Friend JOIN Highschooler ON Friend.friend_id = Highschooler.ID)
SELECT name FROM Highschooler WHERE ID NOT IN (SELECT student_id FROM Friend INNER JOIN Highschooler ON Friend.friend_id = Highschooler.ID WHERE Friend.friend_id IS NULL)
