SELECT DISTINCT Highschooler.ID FROM Highschooler INNER JOIN Friend ON Highschooler.ID = Friend.student_id INNER JOIN Likes ON Highschooler.ID = Likes.student_id
SELECT DISTINCT name FROM Highschooler INNER JOIN Friend ON Highschooler.ID = Friend.student_id INNER JOIN Likes ON Highschooler.ID = Likes.student_id WHERE Likes.liked_id IS NOT NULL;
SELECT name FROM Highschooler WHERE ID IN (SELECT Friend.student_id FROM Friend JOIN Highschooler ON Friend.student_id = Highschooler.ID AND Likes.student_id = Highschooler.ID)
SELECT DISTINCT Highschooler.ID, COUNT(*) AS likes_count FROM Highschooler JOIN Friend ON Highschooler.ID = Friend.student_id GROUP BY Highschooler.ID
SELECT DISTINCT Highschooler.ID, COUNT(*) AS likes_per_student_id FROM Highschooler JOIN Friend ON Highschooler.ID = Friend.student_id GROUP BY Highschooler.ID
SELECT DISTINCT student_id, COUNT(liked_id) AS likes FROM Friend JOIN Likes ON Friend.student_id = Likes.student_id GROUP BY student_id;
SELECT name, COUNT(likes) AS likes_count FROM Highschooler INNER JOIN Likes ON Highschooler.ID = Likes.student_id GROUP BY name;
SELECT name FROM Highschooler JOIN Likes ON Highschooler.ID = Likes.student_id GROUP BY name ORDER BY likes DESC LIMIT 1;
SELECT name FROM Highschooler JOIN Likes ON Highschooler.ID = Likes.student_id GROUP BY name ORDER BY likes DESC LIMIT 1
SELECT name FROM Highschooler JOIN Likes ON Highschooler.ID = Likes.student_id WHERE Likes.liked_id IS NOT NULL;
SELECT name FROM Highschooler WHERE name IN (SELECT name FROM Friend JOIN Likes ON Friend.friend_id = Likes.liked_id WHERE Likes.liked_id IN (SELECT liked_id FROM Likes JOIN Highschooler ON Likes.student_id = Highschooler.ID GROUP BY Highschooler.ID HAVING COUNT(Likes.liked_id) >= 2))
SELECT name FROM Highschooler WHERE grade > 5 AND (SELECT COUNT(*) FROM Highschooler WHERE ID = (SELECT student_id FROM Friend WHERE student_id = (SELECT student_id FROM Highschooler WHERE grade > 5)) AND friend_id = (SELECT friend_id FROM Friend WHERE student_id = (SELECT student_id FROM Highschooler WHERE grade > 5)))
SELECT name FROM Highschooler WHERE grade > 5 AND (SELECT COUNT(*) > 2)
SELECT COUNT(DISTINCT Highschooler.ID) FROM Highschooler;
SELECT COUNT(*) AS number_of_interests FROM Highschooler JOIN Friend ON Highschooler.ID = Friend.student_id JOIN Likes ON Highschooler.ID = Likes.student_id WHERE name = 'Kyle' AND Likes.liked_id IS NULL;
SELECT AVG(likes.grade) FROM Highschooler INNER JOIN Likes ON Highschooler.ID = Likes.student_id;
SELECT AVG(Highschooler.grade) FROM Highschooler JOIN Friend ON Highschooler.ID = Friend.student_id;
SELECT MIN(grade) FROM Highschooler WHERE ID NOT IN (SELECT student_id FROM Friend WHERE friend_id IS NULL OR student_id IS NULL)
SELECT DISTINCT grade FROM Highschooler WHERE ID NOT IN (SELECT student_id FROM Friend WHERE student_id IS NULL OR (SELECT COUNT(*) FROM Likes WHERE liked_id = (SELECT ID FROM Highschooler WHERE ID IS NULL)) > 0)
SELECT owners.state, dogs.dog_id, treatments.treatment_type_code, treatments.date_of_treatment, treatments.cost_of_treatment FROM Owners INNER JOIN Dogs ON Dogs.owner_id = Owners.owner_id INNER JOIN Treatments ON Treatments.dog_id = Dogs.dog_id WHERE dogs.gender = 'M' AND dogs.abandoned_yn = 'Y' AND treatments.treatment_type_code = Treatment_Types.treatment_type_code;
SELECT Owners.state FROM Owners INNER JOIN Dogs ON Dogs.owner_id = Owners.owner_id INNER JOIN Professionals ON Dogs.owner_id = Professionals.professional_id INNER JOIN Treatment_Types ON Treatments.treatment_type_code = Treatment_Types.treatment_type_code INNER JOIN Sizes ON Dogs.size_code = Sizes.size_code INNER JOIN Breeds ON Dogs.breed_code = Breeds.breed_code;
