SELECT Name FROM singer WHERE Net_Worth_Millions = (SELECT MAX(Net_Worth_Millions) FROM singer)
SELECT DISTINCT Name FROM singer ORDER BY Net_Worth_Millions DESC LIMIT 1
SELECT DISTINCT Citizenship, COUNT(*) AS Number_of_Vocalists_per_Citizenship FROM singer GROUP BY Citizenship;
SELECT COUNT(*) AS Total_Musicians FROM singer;
SELECT DISTINCT singer.Name, singer.Citizenship FROM singer JOIN song ON singer.Singer_ID = song.Singer_ID ORDER BY singer.Name ASC;
SELECT singer.Citizenship, COUNT(singer.Singer_ID) AS most_common_vocalist_count FROM singer JOIN song ON singer.Singer_ID = song.Singer_ID GROUP BY singer.Citizenship ORDER BY COUNT(singer.Singer_ID) DESC LIMIT 1;
SELECT DISTINCT singer.Citizenship, MAX(singer.Net_Worth_Millions) AS MaxNetWorth FROM singer GROUP BY singer.Citizenship;
SELECT MAX(Singer.Net_Worth_Millions) AS max_net_worth FROM singer;
SELECT singer.Name, song.Title FROM singer INNER JOIN song ON singer.Singer_ID = song.Singer_ID;
SELECT singer.Name, singer.Citizenship, song.Title, song.Sales, song.Highest_Position FROM singer INNER JOIN song ON singer.Singer_ID = song.Singer_ID;
SELECT DISTINCT singer.Name FROM singer JOIN song ON singer.Singer_ID = song.Singer_ID WHERE song.Sales > 3000000;
SELECT DISTINCT Name FROM singer WHERE Net_Worth_Millions > 300000;
SELECT Name FROM singer JOIN song ON singer.Singer_ID = song.Singer_ID WHERE Sales > 0;
SELECT Name FROM singer WHERE Singer_ID IN (SELECT Singer_ID FROM song GROUP BY Singer_ID HAVING COUNT(Song_ID) > 1)
SELECT singer.Name, SUM(song.Sales) AS Total_Sales FROM singer JOIN song ON singer.Singer_ID = song.Singer_ID GROUP BY singer.Name;
SELECT DISTINCT singer.Name, SUM(song.Sales) AS Total_Sales FROM singer INNER JOIN song ON singer.Singer_ID = song.Singer_ID GROUP BY singer.Name;
SELECT Name FROM singer WHERE Singer_ID NOT IN (SELECT Singer_ID FROM song WHERE Sales IS NULL)
SELECT Name FROM singer WHERE Singer_ID NOT IN (SELECT Singer_ID FROM song WHERE Sales IS NULL)
SELECT Singer_ID, Citizenship FROM singer WHERE Birth_Year < 1945 AND Birth_Year > 1955;
SELECT DISTINCT singer.Citizenship FROM singer JOIN song ON singer.Singer_ID = song.Singer_ID WHERE Birth_Year BETWEEN 1945 AND 1955;
SELECT COUNT(*) AS total_available_characteristic FROM Other_Property_Features;
SELECT DISTINCT feature_type_name FROM Ref_Feature_Types INNER JOIN Other_Available_Features ON Other_Available_Features.feature_type_code = Ref_Feature_Types.feature_type_code;
SELECT Ref_Property_Types.property_type_description FROM Ref_Property_Types JOIN Other_Property_Features ON Other_Property_Features.property_id = Properties.property_id JOIN Other_Available_Features ON Other_Available_Features.feature_id = Other_Property_Features.feature_id JOIN Ref_Feature_Types ON Other_Available_Features.feature_type_code = Ref_Feature_Types.feature_type_code WHERE Other_Property_Features.property_feature_description = 'property type'
SELECT property_name FROM Properties WHERE property_type_code IN ('house', 'apartment') AND room_count > 1;
